mapper.select:
SELECT
COUNT(*)
FROM ${tableName}
where 1=1
AND approve_status = #{approveStatus}

SELECT pt.id, pt.pid, pt.phase_id as phaseId, pt.phase_name as phaseName, pt.name, pt.type, pt.plan_start_time as planStartTime, pt.plan_end_time as planEndTime, pt.priority, pt.status, pt.schedule_status, pt.is_fixed as isFixed, pt.schedule_status, pt.charge_name as chargeName, pt.quote_sys_task_id as quoteSysTaskId, pt.product_id as productId, pt.charge_id as chargeId, pt.process_id as processId, pt.role_name as roleName, pt.distribution_type as distributionType, pt.related_sku_type as relatedSkuType, pt.work_period AS workPeriod, pdi.spu_no AS spu_no FROM project_task pt left join product_info pdi on pt.product_id = pdi.id AND pdi.is_deleted = FALSE left join project_info pji on pdi.id = pji.product_id AND pji.is_deleted = FALSE left join (select task_id,source,array_to_string(array_agg(charge_ids),',') as charge_ids from task_charge_distribution WHERE is_deleted = FALSE group by task_id,source) tcd on pt.id = tcd.task_id and tcd.source = 3 where (pdi.approval_status is null or pdi.approval_status != 4) and (pji.project_status is null or pji.project_status != 4) AND pt.is_deleted = FALSE
AND pt.product_id = #{params.groupFlag}
AND pt.process_id IN
#{processId}
AND pt.plan_end_time >= #{params.startTime}
AND pt.plan_end_time <= #{params.endTime}
AND pt.process_id IN
#{processId}
AND pt.status NOT IN
#{state}
AND pt.name LIKE concat('%',#{params.searchKeyword},'%')
AND (not EXISTS (select a.pre_task_id from pre_task a where a.task_id = pt.id AND a.is_deleted = FALSE ) or not EXISTS (select b.id from pre_task a left join project_task b on a.pre_task_id = b.id and b.is_deleted = false where a.is_deleted = false and (b.status != 4 and b.status != 5) and a.task_id = pt.id ))
AND EXISTS (select b.id from pre_task a left join project_task b on a.pre_task_id = b.id and b.is_deleted = false where a.is_deleted = false and b.status in (0,1,2,3,7) and a.task_id = pt.id)
AND pt.name LIKE concat('%',#{params.taskSearchDTO.searchKeyword},'%')
AND pt.priority in
#{priority}
AND pt.charge_id in
#{chargeId}
AND pt.status in
#{status}
AND pt.create_time >= #{params.taskSearchDTO.startTime}
AND pt.create_time <= #{params.taskSearchDTO.endTime}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
pt.update_time desc
